                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                cells = [(r1+k*sr,c1+k*sc) for k in range(abs(dr)+1)]
                hits = [p for p in sixes if p in cells]
                pairs.append((len(hits), abs(dr), cells, sr, sc, hits))
    if pairs:
        active = [p for p in pairs if p[0] > 0]
        selected = active if active else [max(pairs, key=lambda p:p[1])]
        for _,_,cells,_,_,_ in selected:
            for r,c in cells:
                if out[r][c] != 6:
                    out[r][c] = 1
        for _,_,_,sr,sc,hits in selected:
            for r,c in hits:
                dr,dc=sr,-sc
